import sqlite3
import json
import math
from datetime import datetime
from typing import Dict, Any, List, Optional, Tuple

# Optional (Milvus + embeddings)
USE_MILVUS = True
try:
    from pymilvus import connections, Collection
    from sentence_transformers import SentenceTransformer
except Exception:
    USE_MILVUS = False


# ----------------------
# Fixed configuration (as required)
# ----------------------
sqlite_paths = {
    "business": "D:/Yelp-JSON/db/sqlite3/business.db",
    "checkin": "D:/Yelp-JSON/db/sqlite3/checkin.db",
    "photo": "D:/Yelp-JSON/db/sqlite3/photo.db",
    "review": "D:/Yelp-JSON/db/sqlite3/review.db",
    "tip": "D:/Yelp-JSON/db/sqlite3/tip.db",
    "user": "D:/Yelp-JSON/db/sqlite3/user.db"
}

milvus_config = {
    'milvus_collections': {
        'reviews': 'reviews',
        'photos': 'photo_vector',
        'tips': 'milvus_tip'
    },
    'milvus_host': 'localhost',
    'milvus_port': '19530',
}

neo4j_config = {
    'neo4j_uri': 'bolt://localhost:7687',
    'neo4j_auth': ('neo4j', 'password')
}


# ----------------------
# Helpers
# ----------------------
def connect_sqlite(path: str) -> sqlite3.Connection:
    conn = sqlite3.connect(path)
    conn.row_factory = sqlite3.Row
    return conn


def get_table_columns(conn: sqlite3.Connection, table: str) -> List[str]:
    rows = conn.execute(f"PRAGMA table_info({table})").fetchall()
    return [r[1] for r in rows]


def normalize_day_name(day: str) -> str:
    day = day.strip().lower()
    mapping = {
        'mon': 'Monday', 'monday': 'Monday',
        'tue': 'Tuesday', 'tues': 'Tuesday', 'tuesday': 'Tuesday',
        'wed': 'Wednesday', 'wednesday': 'Wednesday',
        'thu': 'Thursday', 'thurs': 'Thursday', 'thursday': 'Thursday',
        'fri': 'Friday', 'friday': 'Friday',
        'sat': 'Saturday', 'saturday': 'Saturday',
        'sun': 'Sunday', 'sunday': 'Sunday'
    }
    if day not in mapping:
        raise ValueError(f"Unsupported day_of_week: {day}")
    return mapping[day]


def time_to_minutes(t: str) -> int:
    # expects 'HH:MM'
    hh, mm = t.split(':')
    return int(hh) * 60 + int(mm)


def parse_hours_value(hours_value: Any) -> Dict[str, str]:
    """Return dict like {'Friday': '17:00-02:00', ...}

    Supports:
      1) JSON string in a single 'hours' column
      2) Already-parsed dict
    """
    if hours_value is None:
        return {}
    if isinstance(hours_value, dict):
        return hours_value
    if isinstance(hours_value, str):
        s = hours_value.strip()
        if not s:
            return {}
        # common: JSON dict
        if s.startswith('{') and s.endswith('}'):
            try:
                return json.loads(s)
            except Exception:
                return {}
        # otherwise unknown format
        return {}
    return {}


def interval_covers_window(open_interval: str, window_start: str, window_end: str) -> bool:
    """open_interval like '17:00-02:00'; window_end is exclusive-ish but we treat as coverage.

    We consider the restaurant suitable if it is open for the entire window [start, end].
    Handles overnight intervals where close < open.
    """
    if not open_interval or '-' not in open_interval:
        return False
    a, b = [x.strip() for x in open_interval.split('-', 1)]
    try:
        open_m = time_to_minutes(a)
        close_m = time_to_minutes(b)
        ws = time_to_minutes(window_start)
        we = time_to_minutes(window_end)
    except Exception:
        return False

    # window is assumed within same day (21:00-23:00). If you want overnight windows, extend logic.

    if close_m > open_m:
        # same-day closing
        return open_m <= ws and we <= close_m
    else:
        # overnight closing (e.g., 17:00-02:00)
        # Open from open_m..1440 and 0..close_m
        return (open_m <= ws) and (we <= 1440)


def parse_checkin_dates(date_str: str) -> List[datetime]:
    """Yelp checkin 'date' is often like '2019-10-12 00:15:12, 2019-10-12 01:15:12, ...'"""
    if not date_str:
        return []
    parts = [p.strip() for p in date_str.split(',') if p.strip()]
    out = []
    for p in parts:
        # Some datasets include seconds; use robust parse
        for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M"):
            try:
                out.append(datetime.strptime(p, fmt))
                break
            except Exception:
                continue
    return out


def minmax_norm(values: List[float]) -> List[float]:
    if not values:
        return []
    lo, hi = min(values), max(values)
    if hi - lo < 1e-12:
        return [0.0 for _ in values]
    return [(v - lo) / (hi - lo) for v in values]


# ----------------------
# Main query function
# ----------------------
def find_late_dinner_restaurants(
    day_of_week: str = 'Friday',
    window_start: str = '21:00',
    window_end: str = '23:00',
    city: Optional[str] = None,
    state: Optional[str] = None,
    top_n: int = 20,
    enable_milvus: bool = True
) -> List[Dict[str, Any]]:

    day = normalize_day_name(day_of_week)

    # --- Step 1: candidate restaurants from business.db
    bconn = connect_sqlite(sqlite_paths['business'])
    try:
        bcols = set(get_table_columns(bconn, 'business'))
    except Exception as e:
        bconn.close()
        raise RuntimeError("Could not read business table schema") from e

    # Build SELECT with best-effort hours access
    select_cols = [
        'business_id', 'name', 'city', 'state', 'latitude', 'longitude',
        'stars', 'review_count', 'categories', 'is_open'
    ]
    hours_mode = None
    if 'hours' in bcols:
        select_cols.append('hours')
        hours_mode = 'json'
    else:
        # try weekday columns, common patterns
        # e.g. 'hours_Monday' ... or 'Monday'
        weekday_col = None
        candidates = [f"hours_{day}", day, day.lower(), f"{day.lower()}_hours"]
        for c in candidates:
            if c in bcols:
                weekday_col = c
                break
        if weekday_col:
            select_cols.append(f"{weekday_col} as hours_day")
            hours_mode = 'weekday_col'
        else:
            # We can still fetch rows but cannot filter by hours reliably
            hours_mode = 'none'

    where = ["is_open=1", "categories LIKE '%Restaurants%'"]
    params: List[Any] = []
    if city:
        where.append("city = ?")
        params.append(city)
    if state:
        where.append("state = ?")
        params.append(state)

    sql = f"SELECT {', '.join(select_cols)} FROM business WHERE {' AND '.join(where)}"
    rows = bconn.execute(sql, params).fetchall()

    # --- Step 2: filter by open hours in window
    open_rows = []
    if hours_mode == 'none':
        # If no hours available, we cannot guarantee open 9-11pm; return empty with a clear error
        # Alternatively, keep them but flag unknown. Here: keep but mark unknown.
        for r in rows:
            d = dict(r)
            d['_hours_status'] = 'unknown'
            open_rows.append(d)
    else:
        for r in rows:
            d = dict(r)
            hours_for_day = None
            if hours_mode == 'json':
                hours_dict = parse_hours_value(d.get('hours'))
                hours_for_day = hours_dict.get(day)
            elif hours_mode == 'weekday_col':
                hours_for_day = d.get('hours_day')

            if hours_for_day and interval_covers_window(hours_for_day, window_start, window_end):
                d['_hours_status'] = 'covered'
                d['_hours_for_day'] = hours_for_day
                open_rows.append(d)

    # Early stop
    if not open_rows:
        bconn.close()
        return []

    # --- Step 3: late checkin counts
    cconn = connect_sqlite(sqlite_paths['checkin'])
    open_ids = [r['business_id'] for r in open_rows]
    late_checkins: Dict[str, int] = {bid: 0 for bid in open_ids}

    # Chunk to avoid SQLite parameter limits
    chunk_size = 900
    for i in range(0, len(open_ids), chunk_size):
        chunk = open_ids[i:i+chunk_size]
        placeholders = ','.join(['?'] * len(chunk))
        q = f"SELECT business_id, date FROM checkin WHERE business_id IN ({placeholders})"
        for row in cconn.execute(q, chunk).fetchall():
            bid = row['business_id']
            dates = parse_checkin_dates(row['date'])
            cnt = 0
            for dt in dates:
                # Filter by day-of-week and hour window
                if dt.strftime('%A') != day:
                    continue
                if window_start <= dt.strftime('%H:%M') < window_end:
                    cnt += 1
            late_checkins[bid] = late_checkins.get(bid, 0) + cnt

    cconn.close()
    bconn.close()

    # --- Step 4: optional Milvus dinner-related review signals
    milvus_signal: Dict[str, float] = {bid: 0.0 for bid in open_ids}
    if enable_milvus and USE_MILVUS:
        try:
            connections.connect(host=milvus_config['milvus_host'], port=milvus_config['milvus_port'])
            col = Collection(milvus_config['milvus_collections']['reviews'])

            # Try to load collection (needed in some Milvus deployments)
            try:
                col.load()
            except Exception:
                pass

            model = SentenceTransformer('sentence-transformers/all-MiniLM-L6-v2')
            query_text = f"great dinner late night between {window_start} and {window_end}"
            qvec = model.encode([query_text], normalize_embeddings=True).tolist()

            # Heuristic: attempt to infer vector field name
            schema_fields = [f.name for f in col.schema.fields]
            vector_field = None
            for cand in ['embedding', 'vector', 'review_vector', 'text_vector']:
                if cand in schema_fields:
                    vector_field = cand
                    break
            if vector_field is None:
                # fallback to first FLOAT_VECTOR field
                for f in col.schema.fields:
                    if str(f.dtype).endswith('FLOAT_VECTOR'):
                        vector_field = f.name
                        break

            # We also need business_id field name
            business_id_field = None
            for cand in ['business_id', 'biz_id']:
                if cand in schema_fields:
                    business_id_field = cand
                    break

            if vector_field and business_id_field:
                # Milvus filtering expr might be limited by IN size; so we skip filter and aggregate globally.
                # If your collection supports expr with in, add it here.
                res = col.search(
                    data=qvec,
                    anns_field=vector_field,
                    param={"metric_type": "IP", "params": {"nprobe": 16}},
                    limit=300,
                    output_fields=[business_id_field]
                )

                # Aggregate: higher score means more dinner-related reviews
                # Using sum of similarities for businesses in our open set
                open_set = set(open_ids)
                for hits in res:
                    for h in hits:
                        bid = h.entity.get(business_id_field)
                        if bid in open_set:
                            milvus_signal[bid] += float(h.score)
        except Exception:
            # If Milvus is unavailable or schema mismatch, silently degrade
            pass

    # --- Step 5: rank
    stars_vals = [float(r.get('stars') or 0.0) for r in open_rows]
    rc_vals = [math.log1p(float(r.get('review_count') or 0.0)) for r in open_rows]
    lc_vals = [math.log1p(float(late_checkins.get(r['business_id'], 0))) for r in open_rows]
    mv_vals = [math.log1p(float(milvus_signal.get(r['business_id'], 0.0))) for r in open_rows]

    stars_n = minmax_norm(stars_vals)
    rc_n = minmax_norm(rc_vals)
    lc_n = minmax_norm(lc_vals)
    mv_n = minmax_norm(mv_vals)

    # Weights: prioritize stars + review_count; use checkins + milvus as tie-breakers
    w_stars, w_rc, w_lc, w_mv = 0.55, 0.25, 0.20, (0.10 if (enable_milvus and USE_MILVUS) else 0.0)
    # If milvus enabled, renormalize by reducing others slightly
    if w_mv > 0:
        scale = (1.0 - w_mv) / (w_stars + w_rc + w_lc)
        w_stars *= scale
        w_rc *= scale
        w_lc *= scale

    results = []
    for i, r in enumerate(open_rows):
        bid = r['business_id']
        score = w_stars * stars_n[i] + w_rc * rc_n[i] + w_lc * lc_n[i] + w_mv * mv_n[i]
        results.append({
            "business_id": bid,
            "name": r.get('name'),
            "city": r.get('city'),
            "state": r.get('state'),
            "stars": r.get('stars'),
            "review_count": r.get('review_count'),
            "late_checkins_in_window": int(late_checkins.get(bid, 0)),
            "hours_for_day": r.get('_hours_for_day', None),
            "score": float(score),
            "milvus_dinner_signal": float(milvus_signal.get(bid, 0.0)) if (enable_milvus and USE_MILVUS) else None
        })

    results.sort(key=lambda x: x['score'], reverse=True)
    return results[:top_n]


if __name__ == '__main__':
    # ---- Adjust these parameters as needed ----
    # If you don't specify city/state, it will search across the whole dataset (can be slow).
    params = {
        "day_of_week": "Friday",
        "window_start": "21:00",
        "window_end": "23:00",
        "city": None,     # e.g. 'Las Vegas'
        "state": None,    # e.g. 'NV'
        "top_n": 20,
        "enable_milvus": True
    }

    try:
        out = find_late_dinner_restaurants(**params)
        if not out:
            print("No matching restaurants found (or hours not available).")
        else:
            for idx, r in enumerate(out, 1):
                print(f"{idx:02d}. {r['name']} | {r['city']}, {r['state']} | stars={r['stars']} (n={r['review_count']}) | late_checkins={r['late_checkins_in_window']} | hours={r['hours_for_day']} | score={r['score']:.4f}")
    except Exception as e:
        print(f"Error: {e}")

import json
import math
import sqlite3
from dataclasses import dataclass
from datetime import datetime
from typing import Dict, List, Optional, Tuple

# Milvus
from pymilvus import connections, Collection, utility

# Embeddings
try:
    from sentence_transformers import SentenceTransformer
except Exception as e:
    raise RuntimeError(
        "Missing dependency: sentence-transformers. Install with: pip install sentence-transformers"
    ) from e


# -----------------------------
# Fixed configuration (as required)
# -----------------------------
sqlite_paths = {
    "business": "D:/Yelp-JSON/db/sqlite3/business.db",
    "checkin": "D:/Yelp-JSON/db/sqlite3/checkin.db",
    "photo": "D:/Yelp-JSON/db/sqlite3/photo.db",
    "review": "D:/Yelp-JSON/db/sqlite3/review.db",
    "tip": "D:/Yelp-JSON/db/sqlite3/tip.db",
    "user": "D:/Yelp-JSON/db/sqlite3/user.db"
}

milvus_cfg = {
    'milvus_collections': {
        'reviews': 'reviews',
        'photos': 'photo_vector',
        'tips': 'milvus_tip'
    },
    'milvus_host': 'localhost',
    'milvus_port': '19530',
}

neo4j_cfg = {
    'neo4j_uri': 'bolt://localhost:7687',
    'neo4j_auth': ('neo4j', 'password')
}


# -----------------------------
# Helpers
# -----------------------------
@dataclass
class BusinessRow:
    business_id: str
    name: str
    address: str
    city: str
    state: str
    postal_code: Optional[str]
    stars: float
    review_count: int
    categories: Optional[str]
    hours_raw: Optional[str]
    hours_sunday: Optional[str] = None  # if schema has hours_Sunday etc


def connect_sqlite(path: str) -> sqlite3.Connection:
    conn = sqlite3.connect(path)
    conn.row_factory = sqlite3.Row
    return conn


def table_columns(conn: sqlite3.Connection, table: str) -> List[str]:
    rows = conn.execute(f"PRAGMA table_info({table})").fetchall()
    return [r[1] for r in rows]


def parse_hours_sunday(biz: BusinessRow) -> Optional[str]:
    """Return something like '08:00-14:00' if available."""
    # 1) If there is an explicit hours_Sunday column
    if biz.hours_sunday:
        return biz.hours_sunday

    # 2) If hours is a JSON string like {"Sunday": "08:00-14:00", ...}
    if not biz.hours_raw:
        return None

    raw = biz.hours_raw
    # Try JSON
    try:
        obj = json.loads(raw)
        if isinstance(obj, dict):
            return obj.get("Sunday")
    except Exception:
        pass

    # 3) If hours is a non-JSON string (fallback heuristic)
    # e.g., "Sunday: 08:00-14:00; Monday: ..."
    lower = raw.lower()
    if "sunday" in lower:
        # very naive extraction
        parts = raw.split(";")
        for p in parts:
            if "sunday" in p.lower():
                # strip 'Sunday:'
                if ":" in p:
                    return p.split(":", 1)[1].strip()
                return p.strip()
    return None


def time_to_minutes(t: str) -> int:
    hh, mm = t.split(":")
    return int(hh) * 60 + int(mm)


def hours_cover_window(hours_range: str, window_start: str, window_end: str) -> bool:
    """
    hours_range examples: '08:00-14:00' or '08:00-02:00' (cross-midnight).
    window_start/end are within the same morning period (e.g., 09:00-11:30).
    """
    if not hours_range or "-" not in hours_range:
        return False
    start_s, end_s = [x.strip() for x in hours_range.split("-", 1)]

    open_m = time_to_minutes(start_s)
    close_m = time_to_minutes(end_s)
    w_start = time_to_minutes(window_start)
    w_end = time_to_minutes(window_end)

    # handle cross-midnight: treat close as next day
    if close_m < open_m:
        close_m += 24 * 60

    # window is assumed same day morning; if window is before open and business crosses midnight from previous day,
    # this won't be captured; acceptable for brunch use-case.
    return open_m <= w_start and close_m >= w_end


def normalize_scores(d: Dict[str, float]) -> Dict[str, float]:
    if not d:
        return {}
    vals = list(d.values())
    mn, mx = min(vals), max(vals)
    if mx - mn < 1e-9:
        return {k: 1.0 for k in d}
    return {k: (v - mn) / (mx - mn) for k, v in d.items()}


# -----------------------------
# Core pipeline
# -----------------------------

def fetch_candidate_businesses(city: str, state: str) -> List[BusinessRow]:
    conn = connect_sqlite(sqlite_paths["business"])
    cols = table_columns(conn, "business")

    # Determine hours storage
    has_hours_json = "hours" in cols
    has_hours_sunday = "hours_Sunday" in cols

    select_cols = [
        "business_id", "name", "address", "city", "state", "postal_code",
        "stars", "review_count", "categories"
    ]
    if has_hours_json:
        select_cols.append("hours")
    else:
        select_cols.append("NULL as hours")
    if has_hours_sunday:
        select_cols.append("hours_Sunday")
    else:
        select_cols.append("NULL as hours_Sunday")

    # Category keywords for brunch
    # (you can tune this list)
    like_terms = ["%Brunch%", "%Breakfast%", "%Breakfast & Brunch%", "%Cafe%", "%Diners%"]
    like_clause = " OR ".join(["categories LIKE ?" for _ in like_terms])

    sql = f"""
        SELECT {', '.join(select_cols)}
        FROM business
        WHERE city = ? AND state = ?
          AND ({like_clause})
    """
    params = [city, state] + like_terms

    rows = conn.execute(sql, params).fetchall()
    conn.close()

    out: List[BusinessRow] = []
    for r in rows:
        out.append(BusinessRow(
            business_id=r["business_id"],
            name=r["name"],
            address=r["address"],
            city=r["city"],
            state=r["state"],
            postal_code=r["postal_code"] if "postal_code" in r.keys() else None,
            stars=float(r["stars"]) if r["stars"] is not None else 0.0,
            review_count=int(r["review_count"]) if r["review_count"] is not None else 0,
            categories=r["categories"] if "categories" in r.keys() else None,
            hours_raw=r["hours"],
            hours_sunday=r["hours_Sunday"],
        ))
    return out


def filter_open_sunday_morning(businesses: List[BusinessRow], window_start: str = "09:00", window_end: str = "11:30") -> List[Tuple[BusinessRow, Optional[str]]]:
    filtered = []
    for b in businesses:
        sunday = parse_hours_sunday(b)
        if sunday and hours_cover_window(sunday, window_start, window_end):
            filtered.append((b, sunday))
    return filtered


def milvus_connect():
    connections.connect(alias="default", host=milvus_cfg["milvus_host"], port=milvus_cfg["milvus_port"])


def get_collection(name: str) -> Collection:
    if not utility.has_collection(name):
        raise RuntimeError(f"Milvus collection not found: {name}")
    col = Collection(name)
    col.load()
    return col


def infer_vector_field(col: Collection) -> str:
    # pick the first FLOAT_VECTOR field
    for f in col.schema.fields:
        if str(f.dtype) == "DataType.FLOAT_VECTOR":
            return f.name
    raise RuntimeError(f"No FLOAT_VECTOR field found in collection {col.name}")


def infer_id_field(col: Collection) -> str:
    # Heuristic: look for common id fields
    candidates = ["review_id", "tip_id", "id"]
    schema_fields = {f.name for f in col.schema.fields}
    for c in candidates:
        if c in schema_fields:
            return c
    # fallback: choose first non-vector field
    for f in col.schema.fields:
        if str(f.dtype) != "DataType.FLOAT_VECTOR":
            return f.name
    raise RuntimeError(f"No suitable id field found in collection {col.name}")


def embed_query(text: str, dim: int) -> List[float]:
    model = SentenceTransformer("all-MiniLM-L6-v2")
    vec = model.encode([text], normalize_embeddings=True)[0]
    vec = vec.tolist()
    if len(vec) != dim:
        raise RuntimeError(
            f"Embedding dim mismatch: model produced {len(vec)} but Milvus expects {dim}. "
            "Use the same embedding model as used when building the Milvus collection."
        )
    return vec


def search_text_collection(collection_name: str, query_text: str, top_k: int = 200) -> List[Tuple[str, float]]:
    col = get_collection(collection_name)
    vec_field = infer_vector_field(col)
    id_field = infer_id_field(col)

    # infer dim
    dim = None
    for f in col.schema.fields:
        if f.name == vec_field:
            dim = f.params.get("dim")
            break
    if dim is None:
        raise RuntimeError(f"Cannot infer vector dim for {collection_name}.{vec_field}")

    qvec = embed_query(query_text, int(dim))

    search_params = {"metric_type": "IP", "params": {"nprobe": 16}}
    res = col.search(
        data=[qvec],
        anns_field=vec_field,
        param=search_params,
        limit=top_k,
        output_fields=[id_field]
    )

    hits = []
    for hit in res[0]:
        # hit.entity.get(id_field) works in newer pymilvus; fallback to hit.get
        try:
            rid = hit.entity.get(id_field)
        except Exception:
            rid = hit.get(id_field)
        score = float(hit.score)
        hits.append((str(rid), score))
    return hits


def map_review_ids_to_business(review_ids: List[str]) -> Dict[str, str]:
    if not review_ids:
        return {}
    conn = connect_sqlite(sqlite_paths["review"])

    # chunk IN queries to avoid SQLite limits
    out = {}
    chunk_size = 900
    for i in range(0, len(review_ids), chunk_size):
        chunk = review_ids[i:i+chunk_size]
        placeholders = ",".join(["?"] * len(chunk))
        sql = f"SELECT review_id, business_id FROM review WHERE review_id IN ({placeholders})"
        for r in conn.execute(sql, chunk).fetchall():
            out[str(r["review_id"])] = str(r["business_id"])
    conn.close()
    return out


def map_tip_ids_to_business(tip_ids: List[str]) -> Dict[str, str]:
    if not tip_ids:
        return {}
    conn = connect_sqlite(sqlite_paths["tip"])

    out = {}
    chunk_size = 900
    for i in range(0, len(tip_ids), chunk_size):
        chunk = tip_ids[i:i+chunk_size]
        placeholders = ",".join(["?"] * len(chunk))
        sql = f"SELECT tip_id, business_id FROM tip WHERE tip_id IN ({placeholders})"
        for r in conn.execute(sql, chunk).fetchall():
            out[str(r["tip_id"])] = str(r["business_id"])
    conn.close()
    return out


def aggregate_semantic_scores(query_text: str, top_k: int = 200) -> Dict[str, float]:
    milvus_connect()

    # Search reviews
    review_hits = search_text_collection(milvus_cfg['milvus_collections']['reviews'], query_text, top_k=top_k)
    review_id_to_biz = map_review_ids_to_business([rid for rid, _ in review_hits])

    # Search tips
    tip_hits = search_text_collection(milvus_cfg['milvus_collections']['tips'], query_text, top_k=top_k)
    tip_id_to_biz = map_tip_ids_to_business([tid for tid, _ in tip_hits])

    # Aggregate: max score per business from each source, then sum
    biz_scores: Dict[str, float] = {}

    def upd(bid: str, s: float):
        if not bid:
            return
        # keep max per business per source by using max update pattern
        if bid not in biz_scores:
            biz_scores[bid] = s
        else:
            biz_scores[bid] = max(biz_scores[bid], s)

    for rid, score in review_hits:
        bid = review_id_to_biz.get(rid)
        if bid:
            upd(bid, score)

    for tid, score in tip_hits:
        bid = tip_id_to_biz.get(tid)
        if bid:
            upd(bid, score)

    return biz_scores


def recommend_brunch(city: str, state: str, window_start: str = "09:00", window_end: str = "11:30", top_n: int = 10):
    # 1) SQL candidates
    candidates = fetch_candidate_businesses(city, state)

    # 2) Hours filter
    open_list = filter_open_sunday_morning(candidates, window_start, window_end)
    open_by_id = {b.business_id: (b, sun_hours) for b, sun_hours in open_list}

    # 3) Vector semantic boost
    query_text = "brunch sunday morning eggs benedict mimosas breakfast and brunch"
    try:
        semantic_scores = aggregate_semantic_scores(query_text, top_k=200)
    except Exception as e:
        # If Milvus/embedding mismatches, fallback to no semantic ranking
        semantic_scores = {}
        print(f"[WARN] Semantic search unavailable, fallback to SQL-only ranking. Reason: {e}")

    semantic_norm = normalize_scores(semantic_scores)

    # 4) Hybrid rank
    if open_by_id:
        max_rc = max(b.review_count for b, _ in open_list)
    else:
        max_rc = 1

    results = []
    for bid, (b, sun_hours) in open_by_id.items():
        sem = semantic_norm.get(bid, 0.0)
        stars = (b.stars or 0.0) / 5.0
        rc = b.review_count or 0
        rc_norm = math.log1p(rc) / math.log1p(max_rc) if max_rc > 0 else 0.0

        final = 0.55 * sem + 0.30 * stars + 0.15 * rc_norm

        results.append({
            "business_id": b.business_id,
            "name": b.name,
            "address": b.address,
            "city": b.city,
            "state": b.state,
            "postal_code": b.postal_code,
            "stars": b.stars,
            "review_count": b.review_count,
            "categories": b.categories,
            "sunday_hours": sun_hours,
            "semantic_score_norm": round(sem, 4),
            "final_score": round(final, 6),
        })

    results.sort(key=lambda x: x["final_score"], reverse=True)
    return results[:top_n]


