def get_table_columns(conn: sqlite3.Connection, table: str) -> List[str]:
    cur = conn.cursor()
    cur.execute(f"PRAGMA table_info({table});")
    return [r[1] for r in cur.fetchall()]


def safe_parse_attributes(val: Any) -> Dict[str, Any]:
    """Parse Yelp 'attributes' field if stored as JSON or python-dict-like string."""
    if val is None:
        return {}
    if isinstance(val, dict):
        return val
    if not isinstance(val, str):
        return {}

    s = val.strip()
    if not s:
        return {}

    # Try JSON first
    try:
        obj = json.loads(s)
        return obj if isinstance(obj, dict) else {}
    except Exception:
        pass

    # Try python literal (some dumps look like "{'WiFi': "u'free'", ...}")
    try:
        obj = ast.literal_eval(s)
        return obj if isinstance(obj, dict) else {}
    except Exception:
        return {}


def normalize_wifi(v: Any) -> str:
    if v is None:
        return ""
    if isinstance(v, bool):
        return ""
    s = str(v).strip()
    # Normalize common Yelp legacy representations
    # e.g., "u'free'" or "'free'" -> "free"
    if s.startswith("u'") and s.endswith("'"):
        s = s[2:-1]
    if s.startswith("'") and s.endswith("'"):
        s = s[1:-1]
    if s.startswith('"') and s.endswith('"'):
        s = s[1:-1]
    return s.lower()


def truthy(v: Any) -> bool:
    if v is None:
        return False
    if isinstance(v, bool):
        return v
    s = str(v).strip().lower()
    return s in {"true", "1", "yes", "y", "t"}


def build_full_address(row: Dict[str, Any]) -> str:
    parts = []
    for k in ("address", "city", "state", "postal_code"):
        v = row.get(k)
        if v:
            parts.append(str(v).strip())
    return ", ".join([p for p in parts if p])


def main():
    city = "Franklin"
    category_like = "%Coffee%"

    db_path = sqlite_paths["business"]

    try:
        conn = sqlite3.connect(db_path)
        conn.row_factory = sqlite3.Row
    except Exception as e:
        raise SystemExit(f"Failed to connect to SQLite business DB: {e}")

    try:
        # Detect available columns to be robust across different SQLite schemas
        cols = set(get_table_columns(conn, "business"))

        base_select_cols = [
            "business_id", "name", "address", "city", "state", "postal_code", "stars", "categories"
        ]
        select_cols = [c for c in base_select_cols if c in cols]

        # Prefer attributes column if exists
        has_attributes = "attributes" in cols
        if has_attributes:
            select_cols.append("attributes")

        # Some schemas may have exploded attribute columns
        outdoor_col_candidates = [
            "OutdoorSeating",
            "attributes_OutdoorSeating",
            "attribute_OutdoorSeating",
            "outdoor_seating"
        ]
        wifi_col_candidates = [
            "WiFi",
            "attributes_WiFi",
            "attribute_WiFi",
            "wifi"
        ]
        outdoor_col = next((c for c in outdoor_col_candidates if c in cols), None)
        wifi_col = next((c for c in wifi_col_candidates if c in cols), None)
        if outdoor_col and outdoor_col not in select_cols:
            select_cols.append(outdoor_col)
        if wifi_col and wifi_col not in select_cols:
            select_cols.append(wifi_col)

        if "city" not in cols or "categories" not in cols:
            raise RuntimeError("business table must contain at least 'city' and 'categories' columns for this query.")

        sql = f"""
        SELECT {", ".join(select_cols)}
        FROM business
        WHERE city = ?
          AND categories LIKE ?
        """

        cur = conn.cursor()
        cur.execute(sql, (city, category_like))
        candidates = [dict(r) for r in cur.fetchall()]

        filtered = []
        for r in candidates:
            attrs = safe_parse_attributes(r.get("attributes")) if has_attributes else {}

            # OutdoorSeating: read from exploded column if present, else attributes
            if outdoor_col is not None:
                outdoor_val = r.get(outdoor_col)
            else:
                outdoor_val = attrs.get("OutdoorSeating")

            # WiFi: exploded column if present, else attributes
            if wifi_col is not None:
                wifi_val = r.get(wifi_col)
            else:
                wifi_val = attrs.get("WiFi")

            if not truthy(outdoor_val):
                continue

            wifi_norm = normalize_wifi(wifi_val)
            if wifi_norm != "free":
                continue

            filtered.append({
                "name": r.get("name"),
                "address": build_full_address(r),
                "rating": r.get("stars")
            })

        # Sort by rating desc, then name
        filtered.sort(key=lambda x: (x["rating"] is None, -(x["rating"] or 0), x["name"] or ""))

        # Print results
        print(f"Franklin coffee shops with OutdoorSeating=True and WiFi=free: {len(filtered)}")
        for item in filtered:
            print(f"- {item['name']} | {item['address']} | rating={item['rating']}")

    except Exception as e:
        raise SystemExit(f"Query failed: {e}")
    finally:
        try:
            conn.close()
        except Exception:
            pass


if __name__ == "__main__":
    main()
